package bindgen

import (
	"fmt"
	"slices"
	"strings"
)

// Header starts every generated file.
const Header = "// Code generated by tan generate bindings. DO NOT EDIT.\n"

// Generate renders the TypeScript files for res: one <Service>.ts per
// service, models.ts with the shared interfaces and index.ts re-exporting
// every service as a namespace. runtime is the module call is imported
// from (normally "@tangoui/runtime").
func Generate(res *Result, runtime string) (map[string][]byte, error) {
	if len(res.Services) == 0 {
		return nil, ErrNoServices
	}
	files := map[string][]byte{}
	models := map[string]bool{}
	for _, mod := range res.Models {
		models[mod.Name] = true
	}
	var index strings.Builder
	index.WriteString(Header)
	seen := map[string]bool{}
	for _, svc := range res.Services {
		if seen[svc.Name] {
			return nil, fmt.Errorf("%s: service %q is registered twice", svc.Pos, svc.Name)
		}
		seen[svc.Name] = true
		files[svc.Name+".ts"] = []byte(serviceFile(svc, runtime, models))
		fmt.Fprintf(&index, "export * as %s from \"./%s\";\n", svc.Name, svc.Name)
	}
	if len(res.Models) > 0 {
		files["models.ts"] = []byte(modelsFile(res.Models))
		index.WriteString("export type * from \"./models\";\n")
	}
	files["index.ts"] = []byte(index.String())
	return files, nil
}

func serviceFile(svc Service, runtime string, models map[string]bool) string {
	var body strings.Builder
	used := map[string]bool{}
	for _, m := range svc.Methods {
		params := make([]string, len(m.Params))
		args := make([]string, len(m.Params))
		for i, p := range m.Params {
			for _, id := range identifiers(p.Type) {
				if models[id] {
					used[id] = true
				}
			}
			if m.Variadic && i == len(m.Params)-1 {
				params[i] = "..." + p.Name + ": " + arrayOf(p.Type)
				args[i] = "..." + p.Name
			} else {
				params[i] = p.Name + ": " + p.Type
				args[i] = p.Name
			}
		}
		for _, id := range identifiers(m.Result) {
			if models[id] {
				used[id] = true
			}
		}
		body.WriteString("\n")
		if m.Doc != "" {
			body.WriteString("/**\n")
			for _, line := range strings.Split(m.Doc, "\n") {
				body.WriteString(strings.TrimRight(" * "+strings.ReplaceAll(line, "*/", "* /"), " ") + "\n")
			}
			body.WriteString(" */\n")
		}
		callArgs := fmt.Sprintf("%q", svc.Name+"."+m.Name)
		if len(args) > 0 {
			callArgs += ", " + strings.Join(args, ", ")
		}
		fmt.Fprintf(&body, "export function %s(%s): Promise<%s> {\n  return call<%s>(%s);\n}\n",
			m.Name, strings.Join(params, ", "), m.Result, m.Result, callArgs)
	}
	var b strings.Builder
	b.WriteString(Header)
	fmt.Fprintf(&b, "import { call } from %q;\n", runtime)
	if len(used) > 0 {
		names := make([]string, 0, len(used))
		for n := range used {
			names = append(names, n)
		}
		slices.Sort(names)
		fmt.Fprintf(&b, "import type { %s } from \"./models\";\n", strings.Join(names, ", "))
	}
	b.WriteString(body.String())
	return b.String()
}

func modelsFile(models []*Model) string {
	var b strings.Builder
	b.WriteString(Header)
	for _, mod := range models {
		fmt.Fprintf(&b, "\nexport interface %s {\n", mod.Name)
		for _, f := range mod.Fields {
			fmt.Fprintf(&b, "  %s;\n", f.decl())
		}
		b.WriteString("}\n")
	}
	return b.String()
}

// identifiers splits a TS type expression into its identifiers.
func identifiers(ts string) []string {
	return strings.FieldsFunc(ts, func(r rune) bool {
		return !(r == '_' || r == '$' || r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9')
	})
}
